def _profile(obs):
    farms=_get(obs,"farms",[]) or []
    p=int(_get(obs,"player",0) or 0)
    if len(farms)<2:return "unknown"
    opp=farms[1-p]
    hands=len(_get(opp,"hands",[]) or [])
    money=float(_get(opp,"money",0) or 0)
    if hands<=3 and money>=900:return "tape"
    if hands==6 and 600<=money<=700:return "v12parent"
    if hands==6 and money>700:return "v14"
    if hands==6 and money<600:return "m12"
    return "other"

def _active(profile):
    if ACTIVATION=="all":return True
    if ACTIVATION=="tape":return profile=="tape"
    if ACTIVATION=="tape_v12parent":return profile in ("tape","v12parent")
    if ACTIVATION=="tape_allstrong":return profile in ("tape","v12parent","v14","m12")
    if ACTIVATION=="tape_v12parent_v14":return profile in ("tape","v12parent","v14")
    return False

def _front_run(obs,action,step):
    private=_get(obs,"private",{}) or {}
    shed=_get(private,"shed",{}) or {}
    orders=list(action.get("market",[]) or [])
    if len(orders)>=10:return action
    already={}
    for order in orders:
        if isinstance(order,list) and len(order)>=3 and order[0]=="SELL":
            already[order[1]]=already.get(order[1],0)+int(order[2] or 0)
    scheduled={}
    if step+1<len(TRACE_ACTIONS):
        for order in TRACE_ACTIONS[step+1].get("market",[]) or []:
            if isinstance(order,list) and len(order)>=3 and order[0]=="SELL" and order[1] in PREMIUM:
                scheduled[order[1]]=scheduled.get(order[1],0)+int(order[2] or 0)
    prices=_get(_get(obs,"market",{}) or {},"prices",{}) or {}
    choices=[]
    for item,qty in scheduled.items():
        available=max(0,int(shed.get(item,0) or 0)-already.get(item,0))
        qty=min(available,qty)
        if qty>0:choices.append((int(prices.get(item,0) or 0)*qty,item,qty))
    choices.sort(reverse=True)
    for _,item,qty in choices:
        if len(orders)>=10:break
        orders.append(["SELL",item,qty])
    action["market"]=orders[:10]
    return action

def agent(obs,config=None):
    global _MODE
    step=min(int(_get(obs,"step",0) or 0),len(TRACE_ACTIONS)-1)
    if step==0:_MODE=None
    if step==1 and _MODE is None:_MODE=_profile(obs)
    action=copy.deepcopy(TRACE_ACTIONS[step])
    if _active(_MODE):action=_front_run(obs,action,step)
    return action
